#[component]
fn MainSurface(
    state: Signal<ShellState>,
    snapshot: SharedSnapshot,
    on_expand_preview: EventHandler<()>,
    on_collapse_preview: EventHandler<()>,
    on_toggle_preview_block: EventHandler<usize>,
    on_set_preview_layout: EventHandler<PreviewLayoutMode>,
    on_save_document: EventHandler<(String, WorkspaceDocumentInput)>,
    on_run_recipe_document: EventHandler<(String, WorkspaceDocumentInput, bool)>,
) -> Element {
    let _render_span = crate::render_attribution::ComponentRenderSpan::start("MainSurface");
    let active_session_path = snapshot.active_session_path.clone();
    let surface_key = format!(
        "{}:{}",
        active_session_path
            .clone()
            .unwrap_or_else(|| "__empty__".to_string()),
        snapshot.active_view_mode as u8,
    );
    let mut preview_scroll_top = use_signal(|| 0.0_f64);
    let mut preview_scroll_client_height = use_signal(|| PREVIEW_MIN_VIEWPORT_HEIGHT_PX);
    let mut preview_scroll_height = use_signal(|| PREVIEW_MIN_VIEWPORT_HEIGHT_PX);
    let mut preview_reset_key = use_signal(String::new);
    let mut preview_latest_pin_key = use_signal(String::new);
    let mut main_surface_trace_key = use_signal(String::new);
    let preview_reset_session_path = active_session_path.clone();
    let preview_reset_view_mode = snapshot.active_view_mode as u8;
    use_effect(move || {
        let reset_key = format!(
            "{}:{}",
            preview_reset_session_path
                .clone()
                .unwrap_or_else(|| "__empty__".to_string()),
            preview_reset_view_mode
        );
        if *preview_reset_key.read() == reset_key {
            return;
        }
        preview_reset_key.set(reset_key);
        preview_scroll_top.set(0.0);
        preview_scroll_client_height.set(PREVIEW_MIN_VIEWPORT_HEIGHT_PX);
        preview_scroll_height.set(PREVIEW_MIN_VIEWPORT_HEIGHT_PX);
    });
    let preview_latest_pin_request = snapshot
        .active_session
        .as_ref()
        .filter(|session| {
            preview_should_pin_latest_on_open(
                session,
                snapshot.active_view_mode,
                snapshot.preview_layout,
                snapshot.search_active,
            )
        })
        .map(|session| {
            let (session_path, pin_key) = preview_latest_pin_request(session);
            (
                session_path,
                pin_key,
                preview_latest_initial_scroll_top(session),
            )
        });
    let preview_latest_anchor_key = preview_latest_pin_request
        .as_ref()
        .map(|(_, pin_key, _)| pin_key.clone())
        .unwrap_or_default();
    // ⚠ THE PIN IS AN EVENT, NOT A STEADY STATE — and it was written as one.
    //
    // "Open this transcript at its newest turn" is something that happens ONCE
    // per transcript. `preview_latest_pin_request` is recomputed on every
    // render and stays `Some` for as long as the session is hydrated, so a flag
    // derived from `.is_some()` is true forever. It then selected
    // `preview_latest_materialized_window`, which hard-pins
    // `start = len - PREVIEW_BLOCK_WINDOW, end = len` and ignores scroll
    // entirely — so the reader could never reach an older turn by scrolling up,
    // on a surface that had just been taught to hold 600 of them.
    //
    // The pin is therefore released the moment it has been APPLIED (the same
    // `pin_key` latch the scroll effect below already keeps), after which the
    // window is scroll-driven again. Same shape as the daemon-handover veil:
    // arm on a transition, and make sure the transition can END.
    let preview_latest_pin_pending = preview_latest_pin_request
        .as_ref()
        .is_some_and(|(_, pin_key, _)| *preview_latest_pin_key.read() != *pin_key);
    // Named per session rather than a bare bool: two surfaces can be mounted
    // and only the one that asked should read as busy. Read from the SNAPSHOT
    // prop, never from `state` — a reactive read of the signal here subscribed
    // MainSurface to the whole shell and re-rendered it on every write
    // (330/330 measured 2026-08-20); through the props it re-renders exactly
    // when the snapshot content changes.
    let preview_history_expanding_path = snapshot.preview_history_expanding.clone();
    // The pad appears once the reader is far enough from the end to want it —
    // the transcript's answer to the same question the terminal asks in rows
    // against its prompt. No script needed.
    //
    // ⚠ It reads the VIRTUAL WINDOW's geometry, not the raw scroll signals.
    // Those are only written by an `onscroll` event, so on a freshly opened
    // transcript they still hold their initial values and the pad would stay
    // hidden on a 30,000px document until the reader scrolled — which is
    // exactly when they no longer need to be told it exists. The window carries
    // a height estimated from the blocks themselves, so this is right on the
    // first frame.

    use_effect(move || {
        let Some((session_path, pin_key, initial_scroll_top)) = preview_latest_pin_request.clone()
        else {
            return;
        };
        if *preview_latest_pin_key.read() == pin_key {
            return;
        }
        preview_scroll_top.set(initial_scroll_top);
        preview_latest_pin_key.set(pin_key);
        let _ = document::eval(&preview_scroll_to_latest_script(&session_path));
    });
    let render_trace_session_path = active_session_path.clone();
    let render_trace_surface_key = surface_key.clone();
    let render_trace_view_mode = snapshot.active_view_mode;
    let render_trace_session_kind = snapshot
        .active_session
        .as_ref()
        .map(|session| format!("{:?}", session.kind));
    use_effect(move || {
        let trace_key = format!(
            "{}:{:?}:{}",
            render_trace_surface_key,
            render_trace_view_mode,
            render_trace_session_kind
                .clone()
                .unwrap_or_else(|| "__none__".to_string())
        );
        if *main_surface_trace_key.read() == trace_key {
            return;
        }
        main_surface_trace_key.set(trace_key);
        // Peek: `bootstrap.settings_path` never changes after launch, and a
        // reactive read here re-armed this effect on every ShellState write.
        let trace_home = perf_home_dir(&state.peek().bootstrap.settings_path);
        append_trace_event(
            &trace_home,
            "ui",
            "main_surface",
            "render",
            json!({
                "surface_key": render_trace_surface_key,
                "active_view_mode": format!("{:?}", render_trace_view_mode),
                "active_session_path": render_trace_session_path,
            }),
        );
        if render_trace_view_mode == WorkspaceViewMode::Rendered {
            append_trace_event(
                &trace_home,
                "ui",
                "main_surface",
                "viewport_ready",
                json!({
                    "surface_key": render_trace_surface_key,
                    "active_view_mode": format!("{:?}", render_trace_view_mode),
                    "active_session_path": render_trace_session_path,
                    "session_kind": render_trace_session_kind,
                }),
            );
        }
    });
    let rendered_surface_zoom_percent =
        zoom_percent_f32(snapshot.settings.rendered_font_size, 10.0);
    let rendered_surface_zoom_style = format!(
        // `position:relative` so the floating controls anchor to the SURFACE
        // and not to the scrolled content. A pad inside the scroller scrolls
        // away with the page, which is the one thing a scroll control must
        // never do.
        "display:flex; flex-direction:column; min-width:0; min-height:0; width:100%; \
         height:100%; position:relative; zoom:{}%;",
        rendered_surface_zoom_percent
    );
    let preview_surface_visible = snapshot.active_view_mode == WorkspaceViewMode::Rendered;
    let terminal_surface_visible = snapshot.active_view_mode == WorkspaceViewMode::Terminal;
    let preview_layer_transition = if preview_surface_visible {
        standard_decelerate_transition(&["opacity", "transform"])
    } else {
        standard_accelerate_transition(&["opacity", "transform"])
    };
    let terminal_layer_transition = if terminal_surface_visible {
        standard_decelerate_transition(&["opacity", "transform"])
    } else {
        standard_accelerate_transition(&["opacity", "transform"])
    };
    let preview_layer_style = format!(
        "position:absolute; inset:0; display:flex; flex-direction:column; min-width:0; min-height:0; overflow:hidden; \
         padding:{}; background:{}; border-radius:{}; box-shadow:{}; opacity:{}; visibility:{}; pointer-events:{}; transform:{}; transition:{};",
        if snapshot.fullscreen { "0" } else { "24px" },
        snapshot.palette.panel,
        if snapshot.fullscreen { "0" } else { "11px" },
        snapshot.palette.panel_shadow,
        if preview_surface_visible { "1" } else { "0" },
        if preview_surface_visible {
            "visible"
        } else {
            "hidden"
        },
        if preview_surface_visible {
            "auto"
        } else {
            "none"
        },
        if preview_surface_visible {
            "translateY(0)"
        } else {
            "translateY(8px)"
        },
        preview_layer_transition,
    );
    let terminal_layer_style = format!(
        "position:absolute; inset:0; display:flex; flex-direction:column; min-width:0; min-height:0; overflow:hidden; \
         padding:0; background:transparent; border-radius:{}; box-shadow:none; opacity:{}; visibility:{}; pointer-events:{}; transform:{}; transition:{};",
        if snapshot.fullscreen { "0" } else { "11px" },
        if terminal_surface_visible { "1" } else { "0" },
        if terminal_surface_visible {
            "visible"
        } else {
            "hidden"
        },
        if terminal_surface_visible {
            "auto"
        } else {
            "none"
        },
        if terminal_surface_visible {
            "translateY(0)"
        } else {
            "translateY(8px)"
        },
        terminal_layer_transition,
    );
    let retained_terminal_sessions = snapshot.retained_terminal_sessions.clone();
    // The active split group turns the terminal layer into a multi-pane surface
    // ([[campaign-split-view-groups]]). When Some, its members are laid into
    // pane rects (all co-visible); when None the layer paints one full-bleed
    // session exactly as before.
    let active_split_group = snapshot.active_split_group.clone();
    let split_focus_accent = snapshot.theme_accent.clone();
    // A split member's document surface renders INSIDE its pane rect; the
    // full-bleed layer would paint over the sibling pane (Phase 3).
    let active_session_in_split = active_split_group
        .as_ref()
        .zip(snapshot.active_session_path.as_ref())
        .is_some_and(|(group, active)| group.contains(active));
    // Which pane wears the focus ring. Session-keyed until one session seats
    // TWO panes (split-tabs), where the group's remembered active_pane
    // disambiguates ([[campaign-libyggterm]] Phase 3).
    let split_focused_pane_index = active_split_group
        .as_ref()
        .and_then(|group| focused_pane_index(group, snapshot.active_session_path.as_deref()));
    // Pinned WEB panes of the active group (split-tabs): (index, session, tab)
    // triples, precomputed so the rsx loop below stays a plain iteration.
    let pinned_web_panes: Vec<(usize, String, u64)> = active_split_group
        .as_ref()
        .map(|group| {
            group
                .members
                .iter()
                .enumerate()
                .filter_map(|(index, member)| match member.view {
                    SplitMemberView::Web { tab } => {
                        Some((index, member.session.clone(), tab))
                    }
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default();
    let body = if let Some(session) = snapshot.active_session.clone() {
        if session.kind == SessionKind::Document {
            rsx! {
                div {
                    style: "{preview_layer_style}",
                    div {
                        style: "{rendered_surface_zoom_style}",
                        DocumentEditor {
                            key: "{session.session_path}",
                            session: session.clone(),
                            palette: snapshot.palette,
                            server_busy: snapshot.server_busy,
                            on_save: on_save_document,
                            on_run_recipe_document,
                        }
                    }
                }
            }
        } else {
            let visible_rows = visible_preview_block_rows(&session);
            let visible_blocks = visible_rows
                .iter()
                .map(|(_, block)| block.clone())
                .collect::<Vec<_>>();
            let rendered_sections = preview_rendered_sections(&session);
            let conversation_provider = conversation_provider_model_for_session(&session);
            let preview_failure = snapshot.preview_failure.clone();
            let preview_window = preview_virtual_window(
                &visible_blocks,
                *preview_scroll_top.read(),
                *preview_scroll_client_height.read(),
                *preview_scroll_height.read(),
                snapshot.search_active,
            );
            // ⭐ ONE WINDOW, ALWAYS SCROLL-DRIVEN.
            //
            // There used to be a second window here that hard-pinned the last
            // `PREVIEW_BLOCK_WINDOW` blocks and ignored scroll, selected while
            // an "open at the newest turn" flag was set. Every attempt to make
            // that flag turn off failed differently — it was `.is_some()` on a
            // steady state, then a latch in a component-local signal that
            // resets whenever the surface remounts, which for a live session is
            // constantly. Measured after each fix: `pinPending: true, window
            // 572 -> 596` on a 596-block transcript nobody could scroll.
            //
            // So the pin no longer chooses a WINDOW at all. It is what it always
            // meant: a SCROLL POSITION, applied once by the effect above. The
            // window is computed from wherever the reader actually is, so
            // "scrolled to the top" renders the top and no flag can weld it shut.
            let preview_window = preview_window;
            let rendered_rows =
                visible_rows[preview_window.start_index..preview_window.end_index].to_vec();
            let grouped_runs = group_preview_runs(&rendered_rows);
            let effective_preview_layer_style = preview_layer_style.clone();
            let show_failure_placeholder = preview_should_show_blocking_failure_placeholder(
                preview_failure.is_some(),
                grouped_runs.is_empty(),
                rendered_sections.is_empty(),
                false,
            );
            let show_loading_placeholder = preview_should_show_blocking_loading_placeholder(
                snapshot.preview_loading,
                show_failure_placeholder,
                grouped_runs.is_empty(),
                rendered_sections.is_empty(),
                false,
            );
            let terminal_canvas_snapshot =
                TerminalCanvasSnapshot::from_render_snapshot(snapshot.as_ref());
            rsx! {
                div {
                    style: "position:relative; flex:1; min-width:0; min-height:0; overflow:hidden;",
                    div {
                        "data-split-layer": if active_split_group.is_some() { "1" },
                        style: "{terminal_layer_style}",
                        for terminal_session in retained_terminal_sessions.iter().cloned() {
                            {
                                let session_path_str = terminal_session.session_path.clone();
                                let session_mount_epoch =
                                    snapshot_terminal_mount_epoch(
                                        snapshot.as_ref(),
                                        &session_path_str,
                                    );
                                let is_focused_session = snapshot.active_session_path.as_deref()
                                    == Some(session_path_str.as_str());
                                // A session's TerminalCanvas belongs to its
                                // NON-web pane: a Web{tab} member is its own
                                // pinned pane (rendered below), never a host
                                // for this session's terminal.
                                let pane_index = active_split_group
                                    .as_ref()
                                    .and_then(|group| {
                                        group.members.iter().position(|member| {
                                            member.session == session_path_str
                                                && !matches!(
                                                    member.view,
                                                    SplitMemberView::Web { .. }
                                                )
                                        })
                                    });
                                let is_split_pane = pane_index.is_some();
                                let is_focused_pane =
                                    is_split_pane && pane_index == split_focused_pane_index;
                                // A split pane is always co-visible; a lone
                                // session shows only when it is the focused one.
                                let terminal_visible = if is_split_pane {
                                    terminal_surface_visible
                                } else {
                                    terminal_surface_visible && is_focused_session
                                };
                                let geometry_css = match (active_split_group.as_ref(), pane_index) {
                                    (Some(group), Some(idx)) => {
                                        split_pane_rect_css(group.axis, group.ratio, idx)
                                    }
                                    _ => "position:absolute; inset:0; width:100%;".to_string(),
                                };
                                let z_index = if is_split_pane {
                                    if is_focused_pane { "3" } else { "2" }
                                } else if terminal_visible {
                                    "2"
                                } else {
                                    "0"
                                };
                                // Focus ring: an OUTWARD shadow so the ring
                                // lands in the gutter, never inside the pane
                                // rect — a web pane's native webview paints
                                // above all DOM in its rect, so an inset ring
                                // would vanish there. Bright on the focused
                                // PANE (pane-keyed, so a split-tabs session
                                // seated in two panes rings only one),
                                // hairline on the sibling.
                                let focus_ring = if is_split_pane {
                                    if is_focused_pane {
                                        format!("box-shadow: 0 0 0 2px {};", split_focus_accent)
                                    } else {
                                        "box-shadow: 0 0 0 1px rgba(128,128,128,0.35);"
                                            .to_string()
                                    }
                                } else {
                                    String::new()
                                };
                                let terminal_canvas_style = format!(
                                    "{geometry_css} display:flex; flex-direction:column; min-width:0; min-height:0; \
                                     overflow:hidden; contain:layout style; z-index:{z_index}; opacity:{}; visibility:{}; pointer-events:{}; {focus_ring}",
                                    if terminal_visible { "1" } else { "0" },
                                    if terminal_visible { "visible" } else { "hidden" },
                                    if terminal_visible { "auto" } else { "none" },
                                );
                                let focus_group_id = active_split_group
                                    .as_ref()
                                    .map(|group| group.group_id.clone())
                                    .unwrap_or_default();
                                rsx! {
                                    div {
                                        key: "{terminal_session.session_path}:{session_mount_epoch}",
                                        "data-split-pane-index": if let Some(idx) = pane_index { "{idx}" },
                                        "data-split-session": "{session_path_str}",
                                        style: "{terminal_canvas_style}",
                                        // Click-to-focus a co-visible pane. Only
                                        // acts when this is NOT already the focused
                                        // pane, so a click inside the active
                                        // terminal (selection, scroll) is untouched.
                                        // Index-based, so a split-tabs session
                                        // seated in two panes moves the RING, not
                                        // just the session.
                                        onmousedown: move |_| {
                                            if let Some(idx) = pane_index
                                                && !is_focused_pane
                                            {
                                                focus_split_pane_by_index(
                                                    state,
                                                    &focus_group_id,
                                                    idx,
                                                );
                                            }
                                        },
                                        TerminalCanvas {
                                            key: "{terminal_instance_key(&terminal_session.session_path)}:{session_mount_epoch}",
                                            session: terminal_session.clone(),
                                            snapshot: terminal_canvas_snapshot.clone(),
                                            state,
                                            mount_epoch: session_mount_epoch,
                                        }
                                        // A split member's DOCUMENT SURFACE lives
                                        // INSIDE its pane rect (Phase 3): the doc
                                        // covers this pane's terminal only, the
                                        // sibling keeps painting, and the focus
                                        // ring/divider stay in the gutter outside.
                                        // DocumentSurfaceBody's own layer style is
                                        // absolute inset:0, which here resolves
                                        // against the pane container.
                                        if is_split_pane
                                            && snapshot
                                                .document_surfaces
                                                .get(&session_path_str)
                                                .is_some_and(|surface| surface.pane.visible)
                                        {
                                            DocumentSurfaceBody {
                                                snapshot: snapshot.clone(),
                                                state,
                                                session_path: session_path_str.clone(),
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        // Pinned WEB panes (split-tabs, [[campaign-libyggterm]]
                        // Phase 3): a Web{tab} member is a pane of its own —
                        // pure page, no strip/omnibox chrome (the session's
                        // terminal-view pane carries the chrome). The inner
                        // placeholder is the native-surface reconciler's
                        // geometry oracle for exactly this (session, tab), the
                        // pinned twin of `[data-ws-page]`.
                        for (pinned_idx, pinned_session, pinned_tab) in
                            pinned_web_panes.iter().cloned()
                        {
                            {
                                let (pane_axis, pane_ratio, pinned_group_id) = active_split_group
                                    .as_ref()
                                    .map(|group| {
                                        (group.axis, group.ratio, group.group_id.clone())
                                    })
                                    .unwrap_or((SplitAxis::SideBySide, 0.5, String::new()));
                                let geometry_css =
                                    split_pane_rect_css(pane_axis, pane_ratio, pinned_idx);
                                let is_focused_pane =
                                    split_focused_pane_index == Some(pinned_idx);
                                let focus_ring = if is_focused_pane {
                                    format!("box-shadow: 0 0 0 2px {};", split_focus_accent)
                                } else {
                                    "box-shadow: 0 0 0 1px rgba(128,128,128,0.35);".to_string()
                                };
                                let pane_style = format!(
                                    "{geometry_css} display:flex; flex-direction:column; min-width:0; min-height:0; \
                                     overflow:hidden; z-index:{}; opacity:{}; visibility:{}; pointer-events:{}; {focus_ring}",
                                    if is_focused_pane { "3" } else { "2" },
                                    if terminal_surface_visible { "1" } else { "0" },
                                    if terminal_surface_visible { "visible" } else { "hidden" },
                                    if terminal_surface_visible { "auto" } else { "none" },
                                );
                                let focus_group_id = pinned_group_id.clone();
                                rsx! {
                                    div {
                                        key: "split-web-pane:{pinned_group_id}:{pinned_idx}",
                                        "data-split-pane-index": "{pinned_idx}",
                                        "data-split-web-pane": "{pinned_session}",
                                        style: "{pane_style}",
                                        // Chrome-region click-to-focus. Clicks on
                                        // the PAGE never reach the DOM (the native
                                        // webview swallows them) — focusing the
                                        // pinned pane needs this border strip, the
                                        // sidebar, or app-control.
                                        onmousedown: move |_| {
                                            if !is_focused_pane {
                                                focus_split_pane_by_index(
                                                    state,
                                                    &focus_group_id,
                                                    pinned_idx,
                                                );
                                            }
                                        },
                                        div {
                                            style: "flex:1 1 auto; min-height:0; background:#ffffff;",
                                            "data-ws-pinned-session": "{pinned_session}",
                                            "data-ws-pinned-tab": "{pinned_tab}",
                                        }
                                    }
                                }
                            }
                        }
                        if let Some(group) = active_split_group.clone() {
                            {
                                let axis = group.axis;
                                let ratio = group.ratio;
                                let group_id = group.group_id.clone();
                                let first_pct = (ratio.clamp(0.05, 0.95)) * 100.0;
                                let half = SPLIT_GUTTER_PX / 2;
                                // The divider owns the whole gutter as its drag
                                // hit-area and centers a 1px chrome-color line
                                // in it, so the seam is visible and grabbable.
                                let divider_style = match axis {
                                    SplitAxis::SideBySide => format!(
                                        "position:absolute; top:0; height:100%; left:calc({first_pct:.4}% - {half}px); width:{SPLIT_GUTTER_PX}px; \
                                         z-index:5; cursor:col-resize; background:transparent; \
                                         display:flex; justify-content:center; align-items:stretch;"
                                    ),
                                    SplitAxis::Stacked => format!(
                                        "position:absolute; left:0; width:100%; top:calc({first_pct:.4}% - {half}px); height:{SPLIT_GUTTER_PX}px; \
                                         z-index:5; cursor:row-resize; background:transparent; \
                                         display:flex; flex-direction:column; justify-content:center; align-items:stretch;"
                                    ),
                                };
                                let divider_line_style = match axis {
                                    SplitAxis::SideBySide => format!(
                                        "width:1px; background:{};", snapshot.palette.border
                                    ),
                                    SplitAxis::Stacked => format!(
                                        "height:1px; background:{};", snapshot.palette.border
                                    ),
                                };
                                rsx! {
                                    div {
                                        key: "split-divider:{group_id}",
                                        "data-split-divider": "1",
                                        style: "{divider_style}",
                                        onpointerdown: move |evt| {
                                            evt.stop_propagation();
                                            let group_id = group_id.clone();
                                            spawn(async move {
                                                let mut eval = document::eval(
                                                    &split_divider_drag_script(axis, ratio),
                                                );
                                                while let Ok(value) = eval.recv::<f64>().await {
                                                    if value < 0.0 {
                                                        break;
                                                    }
                                                    set_split_group_ratio(
                                                        state,
                                                        &group_id,
                                                        value as f32,
                                                    );
                                                }
                                            });
                                        },
                                        div {
                                            style: "{divider_line_style}",
                                        }
                                    }
                                }
                            }
                        }
                    }
                    div {
                        style: "{effective_preview_layer_style}",
                        div {
                            key: "{session.session_path}:preview-surface",
                            style: "{rendered_surface_zoom_style}",
                            // ⛔ The Expand All / Collapse All / graph-view bar
                            // is GONE (user, 2026-08-03: "should entirely be
                            // scrapped"). The timeline view supersedes the
                            // graph, and the bar was also what pushed every
                            // floating control out of the true top-right.
                            PreviewReadingToolbar {
                                session_path: session.session_path.clone(),
                                palette: snapshot.palette,
                                state,
                            }
                            PreviewScrollController {
                                session_path: session.session_path.clone(),
                                palette: snapshot.palette,
                            }
                            div {
                                key: "{session.session_path}:preview-scroll",
                                "data-preview-scroll": "1",
                                "data-preview-scroll-active": "true",
                                "data-preview-session-path": "{session.session_path}",
                                style: "display:flex; flex-direction:column; gap:14px; min-width:0; min-height:0; overflow:auto; padding:8px 24px 24px 24px; \
                                        overscroll-behavior:contain; scrollbar-gutter:stable;",
                                onscroll: move |evt: ScrollEvent| {
                                    preview_scroll_top.set(evt.data().scroll_top());
                                    preview_scroll_client_height
                                        .set((evt.data().client_height() as f64).max(PREVIEW_MIN_VIEWPORT_HEIGHT_PX));
                                    preview_scroll_height
                                        .set((evt.data().scroll_height() as f64).max(PREVIEW_MIN_VIEWPORT_HEIGHT_PX));
                                },
                                if snapshot.preview_layout == PreviewLayoutMode::Chat {
                                    ConversationWebView {
                                        session: session.clone(),
                                        provider: conversation_provider.clone(),
                                        rendered_sections: rendered_sections.clone(),
                                        show_loading_placeholder,
                                        preview_failure: preview_failure.clone(),
                                        show_failure_placeholder,
                                        preview_window: preview_window.clone(),
                                        visible_block_count: visible_blocks.len(),
                                        grouped_runs: grouped_runs.clone(),
                                        pin_latest_on_mount: preview_latest_pin_pending,
                                        latest_anchor_key: preview_latest_anchor_key.clone(),
                                        preview_history_expanding: preview_history_expanding_path.as_deref()
                                            == Some(session.session_path.as_str()),
                                        palette: snapshot.palette,
                                        on_toggle_block: move |ix| on_toggle_preview_block.call(ix),
                                        on_copy_block: move |text: String| {
                                            copy_preview_block_text(state, text);
                                        },
                                        on_load_older: {
                                            let session_path = session.session_path.clone();
                                            move |_| expand_preview_history(state, session_path.clone())
                                        },
                                    }
                                } else {
                                    div {
                                        style: "width:min(1120px, 100%); margin:0 auto;",
                                        PreviewGraph {
                                            session: session.clone(),
                                            visible_blocks: visible_blocks.clone(),
                                            rendered_sections: rendered_sections.clone(),
                                            palette: snapshot.palette,
                                        }
                                    }
                                }
                            }
                        }
                    }
                    // The DOCUMENT SURFACE: a viewport-placement pane rendered
                    // as shell DOM over the terminal layer. Ordinary DOM — it
                    // clips, z-orders, screenshots and dom-evals like the rest
                    // of the chrome (everything a native child webview cannot).
                    // FULL-BLEED only outside a split: a split member's
                    // document renders INSIDE its pane rect (Phase 3), never
                    // over the sibling.
                    if active_session_in_split {
                        // Split members own their panes; nothing full-bleed.
                    } else if snapshot
                        .document_surfaces
                        .get(&session.session_path)
                        .is_some_and(|surface| surface.pane.visible)
                    {
                        DocumentSurfaceBody {
                            snapshot: snapshot.clone(),
                            state,
                            session_path: session.session_path.clone(),
                        }
                    }
                    // The way BACK from a hidden document surface is the
                    // titlebar's surface-switch slot (`TitlebarSurfaceSwitch`),
                    // not a pill floating over the terminal. There used to be
                    // one here and a second over the document itself: two
                    // copies of one control, each drawn over a viewport that
                    // had reserved no space for it.
                }
            }
        }
    } else {
        rsx! {
            StartPage {
                snapshot: snapshot.clone(),
                state,
            }
        }
    };
    rsx! {
        div {
            key: "{surface_key}",
            style: format!(
                "flex:1; min-width:0; min-height:0; display:flex; flex-direction:column; background:transparent; padding:{};",
                if snapshot.fullscreen {
                    "0"
                } else {
                    "4px"
                }
            ),
            div {
                key: "{surface_key}-body",
                "data-yggterm-main-surface-body": "1",
                style: "display:flex; flex-direction:column; flex:1 1 auto; min-width:0; min-height:0; overflow:hidden; position:relative;",
                {body}
            }
        }
    }
}
