#[component]
fn ConversationWebView(
    session: ManagedSessionView,
    provider: ConversationProviderModel,
    rendered_sections: Vec<SessionRenderedSection>,
    show_loading_placeholder: bool,
    preview_failure: Option<String>,
    show_failure_placeholder: bool,
    preview_window: PreviewVirtualWindow,
    visible_block_count: usize,
    grouped_runs: Vec<PreviewRun>,
    pin_latest_on_mount: bool,
    latest_anchor_key: String,
    preview_history_expanding: bool,
    palette: Palette,
    on_toggle_block: EventHandler<usize>,
    on_copy_block: EventHandler<String>,
    on_load_older: EventHandler<()>,
) -> Element {
    // ⛔ There is ONE reader of "what did this session say", and it is not
    // here. The shell used to ALSO parse the JSONL off disk itself and draw a
    // second chat under the first — same session, two renderers, two visual
    // languages, and only one of them could see a remote agent. The daemon's
    // preview model owns the answer; this component draws it.
    let tokens = conversation_tokens(palette);
    let read_only_attr = provider.read_only.to_string();
    let can_send_attr = provider.can_send.to_string();
    let can_edit_attr = provider.can_edit.to_string();
    let can_refresh_attr = provider.can_refresh.to_string();
    rsx! {
        div {
            "data-conversation-surface": "1",
            "data-conversation-provider-kind": "{provider.kind}",
            "data-conversation-read-only": "{read_only_attr}",
            "data-conversation-can-send": "{can_send_attr}",
            "data-conversation-can-edit": "{can_edit_attr}",
            "data-conversation-can-refresh": "{can_refresh_attr}",
            "data-preview-window-start": "{preview_window.start_index}",
            "data-preview-window-end": "{preview_window.end_index}",
            "data-preview-session-path": "{session.session_path}",
            "data-preview-window-total": "{visible_block_count}",
            // The pin is an EVENT; stamped so a probe can see whether it is
            // still armed rather than inferring it from spacer arithmetic.
            "data-preview-pin-pending": "{pin_latest_on_mount}",
            "data-preview-window-top-spacer": "{preview_window.top_spacer_px.round() as i64}",
            "data-preview-window-bottom-spacer": "{preview_window.bottom_spacer_px.round() as i64}",
            "data-preview-window-total-height": "{preview_window.total_height_px.round() as i64}",
            "data-preview-window-scroll-top": "{preview_window.scroll_top_px.round() as i64}",
            "data-preview-window-client-height": "{preview_window.viewport_height_px.round() as i64}",
            "data-preview-window-scroll-height": "{preview_window.scroll_height_px.round() as i64}",
            "data-preview-window-overscan": "{preview_window.overscan_px.round() as i64}",
            // The reading column, its stylesheet and its theme variables all
            // come from the shared component — this surface no longer owns a
            // width, a gap or a font of its own.
            style: "display:flex; flex-direction:column; min-width:0; width:100%; position:relative;",
            ConversationColumn {
            tokens,
            surface_id: session.session_path.clone(),
            if show_loading_placeholder {
                PreviewLoadingPlaceholder {
                    session: session.clone(),
                    palette,
                }
            }
            if let Some(message) = preview_failure.clone().filter(|_| show_failure_placeholder) {
                PreviewFailurePlaceholder {
                    session: session.clone(),
                    palette,
                    message,
                }
            }
            // The BEGINNING of what has been fetched. Both are here, above the
            // top spacer, so they sit at the true start of the document rather
            // than at the top of whatever the virtual window happens to hold.
            if session.preview.older_available {
                PreviewHistoryControl {
                    session_path: session.session_path.clone(),
                    palette,
                    busy: preview_history_expanding,
                    on_load_older: move |_| on_load_older.call(()),
                }
            }
            // Restores the reader's place after a page lands. Keyed on the
            // block count so it remounts exactly when the transcript grows, and
            // a no-op unless the control armed it — one shot, armed by a click,
            // cleared by the restore, so it can never re-arm itself on a live
            // transcript the way a content-keyed flag would.
            div {
                key: "history-anchor-{visible_block_count}",
                "data-preview-history-anchor-probe": "1",
                style: "height:0; width:100%; pointer-events:none;",
                onmounted: {
                    let session_path = session.session_path.clone();
                    move |_| {
                        let script = preview_history_restore_script(&session_path);
                        async move {
                            let _ = document::eval(&script);
                        }
                    }
                },
            }
            if preview_window.top_spacer_px > 0.0 {
                div {
                    "data-preview-spacer": "top",
                    style: format!("height:{}px; min-height:{}px;", preview_window.top_spacer_px.round(), preview_window.top_spacer_px.round()),
                }
            }
            for run in grouped_runs.into_iter() {
                PreviewRunBlock {
                    session_id: session.id.clone(),
                    run: run.clone(),
                    palette,
                    on_toggle_block: move |ix| on_toggle_block.call(ix),
                    on_copy_block: move |text: String| on_copy_block.call(text),
                }
            }
            if preview_window.bottom_spacer_px > 0.0 {
                div {
                    "data-preview-spacer": "bottom",
                    style: format!("height:{}px; min-height:{}px;", preview_window.bottom_spacer_px.round(), preview_window.bottom_spacer_px.round()),
                }
            }
            div {
                key: "{latest_anchor_key}",
                "data-preview-latest-anchor": "1",
                "data-preview-session-path": "{session.session_path}",
                style: "height:1px; min-height:1px; width:100%; pointer-events:none;",
                onmounted: move |evt| async move {
                    if !pin_latest_on_mount {
                        return;
                    }
                    let _ = evt
                        .scroll_to_with_options(preview_latest_anchor_scroll_options())
                        .await;
                },
            }
            // The summary strip is the FALLBACK, not a companion: a session
            // with a timeline shows the timeline, and a précis printed above
            // the conversation it summarises is noise.
            if visible_block_count == 0 && !rendered_sections.is_empty() {
                RenderedSectionsStrip {
                    sections: rendered_sections.clone(),
                    palette,
                }
            }
            }
        }
    }
}
