async fn terminal_write_with_local_runtime_retry_async(
    endpoint: ServerEndpoint,
    session_path: String,
    data: String,
    trace_home: &Path,
) -> Result<()> {
    match terminal_write_async(endpoint.clone(), session_path.clone(), data.clone()).await {
        Ok(()) => Ok(()),
        Err(error)
            if (session_path.starts_with("local::") || session_path.starts_with("local://"))
                && is_recoverable_local_terminal_runtime_error(&error.to_string()) =>
        {
            append_trace_event(
                trace_home,
                "ui",
                "terminal_io",
                "app_control_write_retry_after_missing_runtime",
                json!({
                    "session_path": session_path,
                    "error": error.to_string(),
                }),
            );
            terminal_ensure_with_retry_async(endpoint.clone(), session_path.clone(), trace_home)
                .await?;
            terminal_write_async(endpoint, session_path, data).await
        }
        Err(error) => Err(error),
    }
}

fn app_control_terminal_input_payload_for_pty(data: &str) -> String {
    let mut normalized = String::with_capacity(data.len());
    let mut chars = data.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch == '\r' {
            normalized.push('\r');
            if chars.peek().is_some_and(|next| *next == '\n') {
                let _ = chars.next();
            }
        } else if ch == '\n' {
            normalized.push('\r');
        } else {
            normalized.push(ch);
        }
    }
    normalized
}

fn app_control_terminal_input_read_nudge_reason(data: &str) -> &'static str {
    let normalized = app_control_terminal_input_payload_for_pty(data);
    let enter_count = normalized.chars().filter(|ch| *ch == '\r').take(2).count();
    if enter_count > 1 || normalized.len() >= 512 {
        APP_CONTROL_TERMINAL_MULTILINE_SEND_REASON
    } else {
        APP_CONTROL_TERMINAL_SEND_REASON
    }
}

fn app_control_terminal_input_write_chunks(data: &str) -> Vec<String> {
    let data = app_control_terminal_input_payload_for_pty(data);
    // A bracketed-paste block is ONE chunk. The per-line split exists to pace
    // Enters, and there are no Enters inside a paste — the receiver is in paste
    // mode, so every `\r` between the markers is a soft newline in its composer.
    // Splitting one would also strand the markers in separate writes for no
    // gain, and a settle delay mid-paste is latency with nothing to settle.
    if yggterm_core::terminal_input::is_bracketed_paste_block(&data) {
        return vec![data];
    }
    let mut chunks = Vec::new();
    let mut start_ix = 0usize;
    for (ix, ch) in data.char_indices() {
        if ch == '\u{3}' && ix + ch.len_utf8() < data.len() {
            if start_ix < ix {
                chunks.push(data[start_ix..ix].to_string());
            }
            chunks.push(ch.to_string());
            start_ix = ix + ch.len_utf8();
        } else if ch == '\r' && ix + ch.len_utf8() < data.len() {
            let end_ix = ix + ch.len_utf8();
            if start_ix < end_ix {
                chunks.push(data[start_ix..end_ix].to_string());
            }
            start_ix = end_ix;
        }
    }
    if start_ix < data.len() {
        chunks.push(data[start_ix..].to_string());
    }
    if chunks.is_empty() {
        chunks.push(data.to_string());
    }
    chunks
}

#[derive(Debug, Clone)]
struct AppControlTerminalWriteReport {
    chunk_count: usize,
    line_chunk_count: usize,
    interrupt_chunk_count: usize,
    interline_read_nudge_count: usize,
    last_chunk_tail: String,
}

impl AppControlTerminalWriteReport {
    fn to_json(&self) -> Value {
        json!({
            "chunk_count": self.chunk_count,
            "line_chunk_count": self.line_chunk_count,
            "interrupt_chunk_count": self.interrupt_chunk_count,
            "interline_read_nudge_count": self.interline_read_nudge_count,
            "last_chunk_tail": self.last_chunk_tail,
        })
    }
}

async fn terminal_write_app_control_input_async(
    endpoint: ServerEndpoint,
    session_path: String,
    visible_session_path: String,
    data: String,
    read_nudge_reason: &'static str,
    trace_home: &Path,
) -> Result<AppControlTerminalWriteReport> {
    let chunks = app_control_terminal_input_write_chunks(&data);
    let chunk_count = chunks.len();
    let multiline_send = read_nudge_reason == APP_CONTROL_TERMINAL_MULTILINE_SEND_REASON;
    let mut line_chunk_count = 0_usize;
    let mut interrupt_chunk_count = 0_usize;
    let mut interline_read_nudge_count = 0_usize;
    let mut last_chunk_tail = String::new();
    let mut chunks = chunks.into_iter().peekable();
    while let Some(chunk) = chunks.next() {
        last_chunk_tail = terminal_tail_chars(&chunk, 80);
        terminal_write_with_local_runtime_retry_async(
            endpoint.clone(),
            session_path.clone(),
            chunk.clone(),
            trace_home,
        )
        .await?;
        if chunk.ends_with('\u{3}') && chunks.peek().is_some() {
            interrupt_chunk_count = interrupt_chunk_count.saturating_add(1);
            sleep(Duration::from_millis(
                APP_CONTROL_TERMINAL_INTERRUPT_SETTLE_MS,
            ))
            .await;
        } else if chunk.ends_with('\r') && chunks.peek().is_some() {
            line_chunk_count = line_chunk_count.saturating_add(1);
            sleep(Duration::from_millis(APP_CONTROL_TERMINAL_LINE_SETTLE_MS)).await;
            if multiline_send
                && line_chunk_count % TERMINAL_APP_CONTROL_MULTILINE_INTERLINE_NUDGE_INTERVAL == 0
            {
                let _ = dispatch_terminal_external_input_read_nudge(
                    &visible_session_path,
                    read_nudge_reason,
                )
                .await;
                interline_read_nudge_count = interline_read_nudge_count.saturating_add(1);
            }
        }
    }
    Ok(AppControlTerminalWriteReport {
        chunk_count,
        line_chunk_count,
        interrupt_chunk_count,
        interline_read_nudge_count,
        last_chunk_tail,
    })
}

async fn terminal_resize_async(
    endpoint: ServerEndpoint,
    session_path: String,
    cols: u16,
    rows: u16,
) -> Result<()> {
    if client_is_shadow_viewer() {
        // Eng-review D8, enforced on BOTH sides now: a differently-sized shadow
        // issuing SIGWINCH would reflow the CLI and scramble the USER's live
        // frame. The daemon denies it; the shadow must not ask either, because
        // the caller treats a resize error as a mount fault. The shadow keeps
        // the two grids equal from its OWN side instead — it pins its xterm to
        // the daemon's PTY grid (`window.__yggtermShadowPinnedGrid`), so the
        // viewer adapts to the session rather than the session to the viewer.
        return Ok(());
    }
    task::spawn_blocking(move || terminal_resize(&endpoint, &session_path, cols, rows))
        .await
        .map_err(|error| anyhow!("joining terminal resize task: {error}"))?
        .map(|_| ())
}
fn spawn_terminal_startup_resize_repair(
    endpoint: ServerEndpoint,
    runtime_session_path: String,
    visible_session_path: String,
    cols: u16,
    rows: u16,
    trace_home: PathBuf,
    source: &'static str,
) {
    if !terminal_geometry_is_usable(cols, rows) {
        return;
    }
    tokio::spawn(async move {
        sleep(Duration::from_millis(180)).await;
        match terminal_resize_async(endpoint, runtime_session_path, cols, rows).await {
            Ok(()) => {
                append_trace_event(
                    &trace_home,
                    "ui",
                    "terminal_mount",
                    "terminal_startup_resize_repair",
                    json!({
                        "session_path": visible_session_path,
                        "cols": cols,
                        "rows": rows,
                        "source": source,
                    }),
                );
            }
            Err(error) => {
                append_trace_event(
                    &trace_home,
                    "ui",
                    "terminal_mount",
                    "terminal_startup_resize_repair_error",
                    json!({
                        "session_path": visible_session_path,
                        "cols": cols,
                        "rows": rows,
                        "source": source,
                        "error": error.to_string(),
                    }),
                );
            }
        }
    });
}
async fn terminal_resize_nudge_async(
    endpoint: ServerEndpoint,
    session_path: String,
    cols: u16,
    rows: u16,
) -> Result<()> {
    if !terminal_geometry_is_usable(cols, rows) {
        return Ok(());
    }
    let nudged_rows = if rows > 6 {
        rows.saturating_sub(1)
    } else {
        rows.saturating_add(1)
    }
    .max(4);
    let _ = terminal_resize_async(endpoint.clone(), session_path.clone(), cols, nudged_rows).await;
    sleep(Duration::from_millis(45)).await;
    let _ = terminal_resize_async(endpoint, session_path, cols, rows).await;
    Ok(())
}
